{"path": "_validate.js", "content": "const fs = require('fs');
const html = fs.readFileSync('website_museum_openrouter-moonshotai-kimi-k3_01.html', 'utf8');

// 1. Extract and syntax-check all inline scripts
const scripts = [...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)];
if (!scripts.length) { console.log('FAIL: no script blocks'); process.exit(1); }
scripts.forEach((m, i) => {
  try { new Function(m[1]); console.log('script[' + i + '] syntax OK (' + m[1].length + ' chars)'); }
  catch (e) { console.log('script[' + i + '] SYNTAX ERROR: ' + e.message); process.exit(1); }
});

// 2. Structural acceptance checks
const checks = [
  ['sticky navbar', /class="[^"]*navbar/],
  ['hero headline', /Museum Night, Reimagined/],
  ['event name', /ARTIFACT: Museum Night/],
  ['date', /18 October 2026/],
  ['time', /19:00/],
  ['venue', /The Old Gallery, Warsaw/],
  ['hero image', /source\.unsplash\.com\/featured\/2400x1400\?museum,night/],
  ['save to calendar btn', /Save to Calendar/i],
  ['ics filename', /artifact-museum-night\.ics/],
  ['ics dtstart', /20261018T190000/],
  ['ics dtend', /20261019T020000/],
  ['Blob usage', /new Blob/],
  ['8 timeline entries', (html.match(/timeline-item/g) || []).length >= 8],
  ['8 artist cards', (html.match(/artist-card/g) || []).length >= 8],
  ['3 ticket tiers', (html.match(/ticket-card/g) || []).length >= 3],
  ['Night Pass €29', /Night Pass[\s\S]{0,400}€29/],
  ['Curator Pass €59', /Curator Pass[\s\S]{0,400}€59/],
  ['Patron Pass €129', /Patron Pass[\s\S]{0,400}€129/],
  ['recommended badge', /recommended/i],
  ['6+ FAQ items', (html.match(/faq-item/g) || []).length >= 6],
  ['newsletter form', /newsletter/i],
  ['inline SVG map', /<svg[\s\S]{0,200}(map|venue)/i],
  ['toast system', /showToast/],
  ['modal ESC close', /Escape/],
  ['IntersectionObserver reveal', /IntersectionObserver/],
  ['smooth scroll', /scroll-behavior:\s*smooth|scrollIntoView/],
  ['meta description', /<meta name="description"/],
  ['og:title', /property="og:title"/],
  ['og:image', /property="og:image"/],
  ['svg favicon data uri', /rel="icon" href="data:image\/svg/],
  ['gold color', /#d6ad60/i],
  ['bg color', /#070506/i],
  ['Georgia serif stack', /Georgia/],
  ['grain/noise overlay', /grain|noise/i],
  ['no external libs', !/<script[^>]+src=|<link[^>]+href="http[^"]*\.css/.test(html)],
  ['checkout modal', /checkout-modal|checkout/],
  ['artist modal', /artist-modal/],
  ['terms checkbox', /co-terms|terms/i],
  ['mobile menu toggle', /nav-toggle|hamburger|menu-btn/i],
];
let fail = 0;
checks.forEach(([name, cond]) => {
  const ok = cond instanceof RegExp ? cond.test(html) : !!cond;
  if (!ok) { console.log('FAIL: ' + name); fail++; }
});
console.log(fail ? fail + ' CHECKS FAILED' : 'ALL ' + checks.length + ' CHECKS PASSED');
process.exit(fail ? 1 : 0);
"}
